#### Floyd-Warshall
```cpp
class Graph {
public:
    int V;
    vector<vector<int>> dist; // 直接存储所有顶点对的最短路径
    Graph(int v) : V(v), dist(v, vector<int>(v, numeric_limits<int>::max())) {
        for (int i = 0; i < V; ++i) {
            dist[i][i] = 0; // 顶点到自身的距离为 0
        }
    }
    void addEdge(int u, int v, int weight) {
        dist[u][v] = min(dist[u][v], weight); // 可能有重边，取最小权值
        // dist[v][u] = min(dist[v][u], weight); // 如果是无向图，打开此注释
    }
};
class Solution {
public:
    void floydWarshall(Graph& graph) {
        int V = graph.V;
        for (int k = 0; k < V; ++k) {
            for (int i = 0; i < V; ++i) {
                for (int j = 0; j < V; ++j) {
                    if (graph.dist[i][k] != numeric_limits<int>::max() &&
                        graph.dist[k][j] != numeric_limits<int>::max()) {
                        graph.dist[i][j] = min(graph.dist[i][j], graph.dist[i][k] + graph.dist[k][j]);
                    }
                }
            }
        }
    }
};
```
最朴素的实现，通过动态规划原理：
-   `dist[i][j]` 表示从顶点 `i` 到顶点 `j` 的最短路径。
-   如果通过中间顶点 `k` 可以使路径更短，则更新 `dist[i][j]`： ![[Pasted image 20250219215718.png|状态转移方程]] 原理是让每一个节点在其他所有节点之间遍历，看是否能找到距离更小的节点，找到了就根据状态方程更新 dist 表

